mapper.update:
UPDATE wecom_msg_log
SET status = #{status}, errcode = #{errcode}, errmsg = #{errmsg},
    invaliduser = #{invaliduser}, msgid = #{msgid}, attempts = #{attempts},
    next_retry_at = #{nextRetryAt}, updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT id, workspace_id, corp_id, agent_id, event_type, touser_text, msgtype, title,
       status, errcode, errmsg, invaliduser, msgid, attempts, next_retry_at, created_at, updated_at
FROM wecom_msg_log

  AND workspace_id = #{workspaceId}
  AND corp_id = #{corpId}

ORDER BY created_at DESC
LIMIT #{limit}
